package vn.rtr.aeris.phone07;
import android.app.*;import android.content.*;import android.net.Uri;import android.webkit.JavascriptInterface;import android.os.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.function.*;import java.util.concurrent.*;
/** Offline mock only. No socket/flight/SDK handle is exposed through this bridge. */
public final class PayloadBridge07{
 public interface Binding{JSONObject get()throws Exception;}public interface Reply{void send(String id,String value);}
 private final Activity activity;private final PayloadFiles07 files;private final BooleanSupplier allowed;private final Binding binding;private final Reply reply;private final Executor executor;private final Handler main=new Handler(Looper.getMainLooper());private String epoch=UUID.randomUUID().toString(),exportId,exportBinding,exportHead;private byte[]exportBytes;private Intent deferred;private int deferredStatus;private boolean foreground,closed;
 public PayloadBridge07(Activity a,BooleanSupplier ok,Binding b,Reply r,Executor ex)throws Exception{activity=a;allowed=ok;binding=b;reply=r;executor=ex;files=new PayloadFiles07(a.getFilesDir().toPath().resolve("payload07"));}
 public synchronized void lifecycle(boolean fg){foreground=fg;epoch=UUID.randomUUID().toString();if(fg&&deferred!=null){Intent d=deferred;int s=deferredStatus;deferred=null;main.post(()->result(9707,s,d));}}
 public synchronized boolean busy(){return exportId!=null;}
 public synchronized void close(){closed=true;foreground=false;epoch=UUID.randomUUID().toString();exportBytes=null;exportId=null;deferred=null;}
 private void context()throws Exception{if(closed||!foreground||!allowed.getAsBoolean())throw new IOException("MOCK_TRUSTED_FOREGROUND_OFFLINE_ONLY");}
 private boolean sameBinding(String text)throws Exception{JSONObject a=new JSONObject(text),b=binding.get();if(a.length()!=3)return false;for(String k:new String[]{"workspaceHead","modelSha256","planSha256"})if(!a.getString(k).equals(b.getString(k)))return false;return true;}
 private void guard(String e,String expectedBinding)throws Exception{context();if(!epoch.equals(e))throw new IOException("NATIVE_EPOCH_CHANGED_RELOAD_REQUIRED");if(!sameBinding(expectedBinding))throw new IOException("COMMITTED_MISSION_CHANGED");if(files.pending())throw new IOException("JOURNAL_PENDING_READ_ONLY");}
 private String ok(JSONObject o){try{o.put("ok",true);return o.toString();}catch(Exception e){return error(e);}}
 private String error(Exception e){return Data97.json(Data97.m("ok",false,"error",String.valueOf(e.getMessage()),"noRetry",true));}
 private JSONObject snapshot()throws Exception{DraftStore.Snapshot s=files.load();JSONArray rows=new JSONArray();for(DraftStore.Snapshot row:files.history())rows.put(new JSONObject(new String(row.bytes,StandardCharsets.UTF_8)));return new JSONObject().put("epoch",epoch).put("head",s==null?"ROOT":s.token).put("rows",rows).put("binding",binding.get()).put("usageBytes",files.usage()).put("limitBytes",PayloadFiles07.MAX).put("directories",new JSONArray(files.directories())).put("authorityRestored",false).put("sourceKind","SYNTHETIC");}
 @JavascriptInterface public synchronized String bootstrap(){try{context();return ok(snapshot());}catch(Exception e){return error(e);}}
 @JavascriptInterface public synchronized String check(String e,String b){try{guard(e,b);return ok(new JSONObject());}catch(Exception x){return error(x);}}
 private JSONObject appendRaw(String expected,String kind,JSONObject data,JSONObject b)throws Exception{if(!kind.matches("[A-Z0-9_]{1,48}")||data.toString().length()>66000||data.toString().matches("(?s).*\"(?:token|leaseToken|password|privateKey)\"\\s*:.*"))throw new IOException("RECORD_SCHEMA_OR_SECRET");JSONObject row=new JSONObject().put("kind",kind).put("data",data).put("binding",b).put("sourceKind","SYNTHETIC").put("actualImages",0).put("atMonotonicMs",SystemClock.elapsedRealtime()).put("epoch",epoch);DraftStore.Snapshot s=files.append(expected,row.toString().getBytes(StandardCharsets.UTF_8));return new JSONObject().put("head",s.token);}
 @JavascriptInterface public synchronized String append(String e,String b,String expected,String kind,String data){try{guard(e,b);return ok(appendRaw(expected,kind,new JSONObject(data),binding.get()));}catch(Exception x){return error(x);}}
 private byte[]decode(String s,int bound)throws Exception{if(s==null||s.length()>((bound+2)/3)*4)throw new IOException("BASE64_BOUND");byte[]b=Base64.getDecoder().decode(s);if(b.length>bound||!Base64.getEncoder().encodeToString(b).equals(s))throw new IOException("BASE64_CANONICAL");return b;}
 @JavascriptInterface public synchronized String commit(String e,String b,String expected,String id,String image,String sidecar,String manifest,String link){try{guard(e,b);if(!files.history().isEmpty()&&!files.load().token.equals(expected))throw new IOException("STALE_HEAD");JSONObject m=new JSONObject(manifest),l=new JSONObject(link);byte[]original=decode(image,PayloadFiles07.MAX_IMAGE),side=decode(sidecar,32768);if(m.getInt("schemaVersion")!=1||!"AERIS_SYNTHETIC_CAPTURE_PACKAGE".equals(m.getString("kind"))||!"SYNTHETIC".equals(m.getString("sourceKind"))||m.getInt("actualImages")!=0||!id.equals(m.getString("captureId"))||!id.equals(l.getString("captureId"))||!"aeris-gateway01-mock".equals(m.getString("senderId"))||!"rtr-host01-evaluator".equals(m.getString("receiverId"))||!sameBinding(l.getJSONObject("mission07").toString()))throw new IOException("CAPTURE_CONTEXT");JSONArray entries=m.getJSONArray("files");if(entries.length()!=2)throw new IOException("MANIFEST_FILES");byte[][]raw={original,side,manifest.getBytes(StandardCharsets.UTF_8),link.getBytes(StandardCharsets.UTF_8)};for(int i=0;i<2;i++){JSONObject f=entries.getJSONObject(i);if(!f.getString("path").equals(i==0?"original.jpg":"sidecar.json")||f.getInt("sizeBytes")!=raw[i].length||!DraftStore.hash(raw[i]).equals(f.getString("sha256")))throw new IOException("FILE_HASH_SIZE");}if(original[0]!=(byte)255||original[1]!=(byte)216||original[original.length-2]!=(byte)255||original[original.length-1]!=(byte)217)throw new IOException("JPEG_ENVELOPE");Map<String,String>hashes=files.put(id,raw);JSONObject receipt=new JSONObject().put("captureId",id).put("packageId",m.getString("packageId")).put("hashes",new JSONObject(hashes));return ok(appendRaw(expected,"CAPTURE_COMMITTED",receipt,binding.get()));}catch(Exception x){return error(x);}}
 private Map<String,byte[]>readCommitted(String id)throws Exception{JSONObject receipt=null;for(DraftStore.Snapshot row:files.history()){JSONObject r=new JSONObject(new String(row.bytes,StandardCharsets.UTF_8));if("CAPTURE_COMMITTED".equals(r.getString("kind"))&&id.equals(r.getJSONObject("data").optString("captureId"))){receipt=r.getJSONObject("data");break;}}if(receipt==null)throw new IOException("UNCOMMITTED_CAPTURE");Map<String,byte[]>result=new LinkedHashMap<>();for(String name:new String[]{"original.jpg","sidecar.json","manifest.json","gateway.json"})result.put(name,files.read(id,name,receipt.getJSONObject("hashes").getString(name)));return result;}
 @JavascriptInterface public synchronized String read(String id){try{context();JSONObject r=new JSONObject();for(Map.Entry<String,byte[]>f:readCommitted(id).entrySet())r.put(f.getKey(),Base64.getEncoder().encodeToString(f.getValue()));return ok(r);}catch(Exception x){return error(x);}}
 private byte[]tar(Map<String,byte[]>m)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();for(String name:new String[]{"manifest.json","original.jpg","sidecar.json"}){byte[]b=m.get(name),h=new byte[512];put(h,0,name);put(h,100,"0000600");put(h,108,"0000000");put(h,116,"0000000");put(h,124,String.format(Locale.ROOT,"%011o",b.length));put(h,136,"00000000000");Arrays.fill(h,148,156,(byte)32);h[156]='0';put(h,257,"ustar");put(h,263,"00");int sum=0;for(byte x:h)sum+=x&255;put(h,148,String.format(Locale.ROOT,"%06o",sum));h[155]=32;out.write(h);out.write(b);out.write(new byte[(512-b.length%512)%512]);}out.write(new byte[1024]);return out.toByteArray();}
 private void put(byte[]b,int at,String s){byte[]v=s.getBytes(StandardCharsets.US_ASCII);System.arraycopy(v,0,b,at,v.length);}
 @JavascriptInterface public synchronized String export(String request,String e,String b,String id){try{guard(e,b);if(exportId!=null||!request.matches("[a-f0-9-]{36}"))throw new IOException("EXPORT_BUSY_OR_ID");exportBytes=tar(readCommitted(id));exportId=request;exportBinding=b;DraftStore.Snapshot s=files.load();JSONObject receipt=appendRaw(s==null?"ROOT":s.token,"EXPORT_REQUESTED",new JSONObject().put("captureId",id).put("sha256",DraftStore.hash(exportBytes)).put("authorityRestored",false),binding.get());exportHead=receipt.getString("head");main.post(()->{synchronized(this){try{guard(e,b);Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/x-tar").putExtra(Intent.EXTRA_TITLE,"AERIS-"+id+".tar");activity.startActivityForResult(i,9707);}catch(Exception x){clearExport();reply.send(request,error(x));}}});return ok(new JSONObject().put("head",exportHead).put("status","PICKER_REQUESTED"));}catch(Exception x){return error(x);}}
 private void clearExport(){exportId=null;exportBytes=null;exportBinding=null;exportHead=null;}
 public synchronized void result(int code,int status,Intent data){if(code!=9707||exportId==null)return;if(!foreground){deferred=data==null?new Intent():data;deferredStatus=status;return;}final String id=exportId,b=exportBinding,head=exportHead;final byte[]bytes=exportBytes;clearExport();try{context();if(!sameBinding(b)||!files.load().token.equals(head)||status!=Activity.RESULT_OK||data==null||data.getData()==null||!"content".equals(data.getData().getScheme()))throw new IOException("EXPORT_CANCELLED_OR_CONTEXT_CHANGED");final Uri uri=data.getData();final String operationEpoch=epoch;executor.execute(()->{try{synchronized(this){guard(operationEpoch,b);}try(OutputStream out=activity.getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("EXPORT_NO_PROVIDER_OUTPUT");out.write(bytes);out.flush();}ByteArrayOutputStream read=new ByteArrayOutputStream();try(InputStream in=activity.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("EXPORT_NO_READBACK");byte[]block=new byte[4096];int n;while((n=in.read(block))!=-1){if(read.size()+n>600000)throw new IOException("EXPORT_READBACK_BOUND");read.write(block,0,n);}}if(!Arrays.equals(bytes,read.toByteArray()))throw new IOException("EXPORT_READBACK_MISMATCH");synchronized(this){guard(operationEpoch,b);JSONObject r=appendRaw(head,"EXPORT_READBACK",new JSONObject().put("sha256",DraftStore.hash(bytes)).put("bytes",bytes.length).put("providerReadback",true),binding.get());r.put("providerReadback",true);reply.send(id,ok(r));}}catch(Exception x){reply.send(id,error(x));}});}catch(Exception x){reply.send(id,error(x));}}
}
